-- SisterMart 退貨政策 — upsert article_i18n for code=return
INSERT INTO articles (code, status, show_in_footer, sort_order, created_at, updated_at)
SELECT 'return', 1, 1, 90, NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM articles WHERE code='return');
UPDATE articles SET status=1, show_in_footer=1, sort_order=90, updated_at=NOW() WHERE code='return';

INSERT INTO article_i18n (article_id, locale, title, body)
SELECT a.id, 'zh-HK', '退貨政策', '<p><strong>生效日期：</strong>2026 年 11 月 7 日<br>\n<strong>最後更新日期：</strong>2026 年 11 月 7 日</p>\n<p>本《退貨政策》適用於 SisterMart（姐妹商店，網站 sistermart.vip）之香港訂單，並與《退款政策》《運送政策》《用戶協議》一併適用。提出退貨／換貨即表示你已閱讀並同意本政策。為保障交易公平與店舖可持續經營，我們保留在合理範圍內審核、要求補證、拒絕不符合條件之申請，以及按實際情況酌情處理之權利。</p>\n\n<h2>1. 申請時限</h2>\n<ul>\n<li>一般售後申請須於<strong>簽收之日起計 7 日內</strong>（或結帳／活動頁另行標明之較短期限內）透過訂單售後入口或客服提交；逾期未提出且無合理延遲理由者，我們可拒絕受理。</li>\n<li>「質量問題／貨不對板」亦須在上述時限內提出，並提供清晰照片或影片等證據。</li>\n<li>活動、清貨、預售或個別商品頁若標示更短或不可退換，以該標示為準。</li>\n</ul>\n\n<h2>2. 可申請情形（須同時符合）</h2>\n<ol>\n<li><strong>質量問題或描述嚴重不符：</strong>商品存在影響正常使用之重大瑕疵，或與商品頁關鍵描述明顯不符（不含合理色差、手感／光線差異、個人主觀喜好）。</li>\n<li><strong>物流損壞：</strong>外箱或商品明顯運輸破損，須於簽收後儘快（建議 48 小時內）拍照取證並聯絡我們。</li>\n<li><strong>錯發／漏發：</strong>經核對訂單後確認發錯款式／規格或漏發，我們可安排補發、換貨或按《退款政策》處理。</li>\n<li><strong>其他經我們書面同意之情形：</strong>非上述類型之退換（例如個人原因），僅在商品仍符合第 4 節狀態要求、且我們事先同意受理時適用；我們可收取合理手續費／補貨成本或要求顧客承擔運費。</li>\n</ol>\n\n<h2>3. 不適用或可拒絕之情形</h2>\n<p>下列情況我們有權拒絕退貨、換貨或僅提供有限協助（法律另有強制規定者除外）：</p>\n<ul>\n<li>已穿戴、試戴過久、沾污、刮花、變形、裁剪、自行改裝或洗滌之商品</li>\n<li>缺乏原包裝、吊牌、防偽／質檢標、附送配件、證書或發票／出貨清單，影響二次銷售</li>\n<li>個人衛生相關商品（如耳針／耳釘已拆封試戴、貼身飾品護理耗材、已開封護膚美容耗材等）</li>\n<li>訂製、刻字、改尺碼／改鏈長、接單生產或明確標示「不設退換」之商品</li>\n<li>特價清貨、福袋、贈品、積分商城兌換商品（另有說明者除外）</li>\n<li>因個人喜好、尺碼估錯、色差屬合理範圍、或未按保養說明導致之問題</li>\n<li>超過申請時限、無法提供有效訂單與簽收資訊、或拒絕配合檢驗／補證</li>\n<li>經判定存在欺詐、惡意批量退貨、調包或明顯濫用售後之情形</li>\n</ul>\n\n<h2>4. 退回商品狀態要求</h2>\n<p>除經我們確認之質量問題且無法原狀退回之情形外，退回商品須：</p>\n<ul>\n<li>保持可二次銷售之全新／近新狀態</li>\n<li>完整原廠或出貨包裝、配件與贈品一併退回</li>\n<li>未經穿戴使用（珠寶飾品尤須未刮花、未改裝、未接觸化學品／香水過度）</li>\n</ul>\n<p>我們收貨後有權開箱檢驗、拍照存證。若狀態不符、配件缺失或與申請描述不符，可<strong>拒絕退貨／退款</strong>、要求補寄缺件、改為換貨，或在扣除貶值／缺件／運費後再處理（具體以書面通知為準）。</p>\n\n<h2>5. 辦理流程</h2>\n<ol>\n<li>在訂單提交售後申請，或電郵 <strong>service@sistermart.vip</strong>／WhatsApp <strong>+852 5598 3063</strong>，提供訂單編號、商品、問題說明與證據。</li>\n<li>等候我們審核。審核通過後，按指引退回指定地址；<strong>未經同意擅自寄回者，我們可拒收或不予處理</strong>，相關費用由寄件方承擔。</li>\n<li>請自行妥善包裝並保留寄件證明；寄回途中遺失／損壞之風險，除質量問題且我們同意承擔運費之情形外，一般由顧客承擔。</li>\n<li>我們收貨檢驗合格後，再安排換貨或進入《退款政策》流程；檢驗及內部處理通常需要數個工作天。</li>\n</ol>\n\n<h2>6. 運費與費用分擔</h2>\n<ul>\n<li><strong>非質量問題</strong>（含個人原因且經同意受理）：寄回運費、再寄出運費及可能產生之手續／檢測／補貨成本，原則由顧客承擔；原訂單運費是否退還見《退款政策》。</li>\n<li><strong>經確認之質量問題／錯發：</strong>我們承擔合理範圍內之寄回運費（須按我們指定方式；超額或非必要加急費用可不獲報銷）。</li>\n<li>因地址錯誤、拒收、長期不取件導致退回之訂單，補寄或再派費用可由顧客承擔。</li>\n</ul>\n\n<h2>7. 換貨</h2>\n<p>換貨視庫存而定，並非一經申請即保證。若無同款庫存，我們可提供其他方案（延期、更換其他在售商品並多退少補，或按《退款政策》退款）。換貨商品一經發出，適用與新品相同之售後規則。</p>\n\n<h2>8. 證據與溝通</h2>\n<p>我們可要求你提供開箱影片、瑕疵特寫、包裝外觀、物流面單等。未在合理期限內補證，可視為放棄申請。客服溝通紀錄、系統日誌與檢驗結果可作為處理依據。</p>\n\n<h2>9. 酌情與最終處理</h2>\n<p>為平衡消費者保障與店家合法經營，對於灰色地帶個案，SisterMart 可在核實事實後作出合理酌情決定（包括部分退款、僅換貨、補發配件、優惠券折讓或拒絕）。我們會說明主要理由。惡意爭議或不實陳述者，我們保留限制售後、取消優惠或依法追償之權利。</p>\n\n<h2>10. 聯絡與政策更新</h2>\n<p>查詢請聯絡 service@sistermart.vip 或 WhatsApp +852 5598 3063。我們可不時更新本政策；更新後以本頁最新版本為準，對更新前已提交且受理中之申請，原則按提交時規則處理，法律另有規定除外。</p>\n'
FROM articles a WHERE a.code='return'
ON DUPLICATE KEY UPDATE title=VALUES(title), body=VALUES(body);

INSERT INTO article_i18n (article_id, locale, title, body)
SELECT a.id, 'en', 'Return Policy', '<p><strong>Effective date:</strong> 7 November 2026<br>\n<strong>Last updated:</strong> 7 November 2026</p>\n<p>This Return Policy applies to SisterMart (sistermart.vip) Hong Kong orders and should be read with the Refund Policy, Shipping Policy and User Agreement. By requesting a return/exchange you agree to this Policy. To keep trade fair and the shop sustainable, we may review requests, ask for evidence, refuse ineligible claims, and handle cases with reasonable discretion.</p>\n\n<h2>1. Time limits</h2>\n<ul>\n<li>After-sales requests must generally be submitted within <strong>7 days of delivery receipt</strong> (or a shorter period stated at checkout/on the product page) via the order after-sales flow or customer service. Late requests without a reasonable excuse may be refused.</li>\n<li>Quality issues / major misdescription must also be raised within that window, with clear photos or video.</li>\n<li>Campaign, clearance, pre-order or product-page rules that set a shorter or non-returnable term prevail for those items.</li>\n</ul>\n\n<h2>2. Eligible situations (all applicable conditions must be met)</h2>\n<ol>\n<li><strong>Quality defect or serious misdescription:</strong> a material defect affecting normal use, or a clear mismatch with key product-page facts (excluding reasonable colour/feel/lighting variance or subjective preference).</li>\n<li><strong>Transit damage:</strong> obvious shipping damage to outer box or item—please document with photos ASAP after receipt (ideally within 48 hours) and contact us.</li>\n<li><strong>Wrong / missing item:</strong> after we verify the order, we may reship, exchange or follow the Refund Policy.</li>\n<li><strong>Other cases we agree to in writing:</strong> non-defect returns (e.g. change of mind) only if the item meets Section 4 and we pre-approve; we may charge a reasonable handling/restocking cost or require you to pay shipping.</li>\n</ol>\n\n<h2>3. Non-returnable / refusals</h2>\n<p>We may refuse return/exchange or offer only limited help (unless mandatory law requires otherwise) where:</p>\n<ul>\n<li>the item was worn, tried for prolonged use, stained, scratched, bent, altered, cut or washed</li>\n<li>original packaging, tags, seals, accessories, certificates or packing list are missing and resale is affected</li>\n<li>hygiene-related items (e.g. opened/tried ear studs, intimate jewellery care consumables, opened beauty consumables)</li>\n<li>custom, engraved, resized/re-chained, made-to-order, or clearly marked non-returnable items</li>\n<li>clearance, mystery bags, free gifts, or points-mall redemptions (unless otherwise stated)</li>\n<li>issues caused by preference, wrong size estimate, reasonable colour variance, or failure to follow care instructions</li>\n<li>the request is late, lacks valid order/receipt info, or you refuse inspection/evidence</li>\n<li>fraud, serial abusive returns, item swapping or clear after-sales abuse is found</li>\n</ul>\n\n<h2>4. Condition of returned goods</h2>\n<p>Except confirmed defects where original condition cannot be restored, returns must:</p>\n<ul>\n<li>be new/near-new and resalable</li>\n<li>include original/outbound packaging, accessories and gifts</li>\n<li>be unworn (jewellery must be unscratched, unaltered, not heavily exposed to chemicals/perfume)</li>\n</ul>\n<p>We may open, inspect and photograph returns. If condition, missing parts or description do not match, we may <strong>refuse return/refund</strong>, ask you to send missing parts, switch to exchange, or proceed only after deducting depreciation/missing parts/shipping (as notified in writing).</p>\n\n<h2>5. Process</h2>\n<ol>\n<li>Submit after-sales on the order, or email <strong>service@sistermart.vip</strong> / WhatsApp <strong>+852 5598 3063</strong> with order number, items, description and evidence.</li>\n<li>Wait for approval. Then ship to the address we provide. <strong>Unauthorised returns may be refused</strong>; related costs are yours.</li>\n<li>Pack carefully and keep the shipping proof. Risk of loss/damage in transit is generally yours unless we confirmed a quality issue and agreed to cover return shipping.</li>\n<li>After inbound inspection passes, we arrange exchange or start the Refund Policy flow. Inspection and internal handling usually take several business days.</li>\n</ol>\n\n<h2>6. Shipping and costs</h2>\n<ul>\n<li><strong>Non-quality returns</strong> (including approved change-of-mind): return shipping, reship shipping and any handling/inspection/restocking costs are generally yours; original outbound shipping refunds follow the Refund Policy.</li>\n<li><strong>Confirmed quality issues / wrong items:</strong> we cover reasonable return shipping via our instructed method (excess or unnecessary express fees may be excluded).</li>\n<li>Returns caused by wrong address, refusal or long unclaimed parcels may require you to pay reship fees.</li>\n</ul>\n\n<h2>7. Exchanges</h2>\n<p>Exchanges depend on stock and are not guaranteed. If the same item is unavailable, we may offer alternatives (wait, swap for another in-stock item with balance settlement, or refund per the Refund Policy). Exchanged goods follow the same after-sales rules as new items once shipped.</p>\n\n<h2>8. Evidence and records</h2>\n<p>We may request unboxing video, close-ups, packaging shots and courier labels. Failure to provide evidence within a reasonable time may be treated as withdrawal. Support chats, system logs and inspection results may be used to decide the case.</p>\n\n<h2>9. Discretion and final handling</h2>\n<p>For borderline cases, SisterMart may make a reasonable discretionary decision after verification (partial refund, exchange only, spare parts, coupon goodwill, or refusal), and will explain the main reasons. For bad-faith disputes or false statements, we may limit after-sales, cancel benefits or seek remedies under law.</p>\n\n<h2>10. Contact and updates</h2>\n<p>Contact service@sistermart.vip or WhatsApp +852 5598 3063. We may update this Policy; the latest version on this page applies. Requests already accepted before an update are generally handled under the rules at submission time, unless law requires otherwise.</p>\n'
FROM articles a WHERE a.code='return'
ON DUPLICATE KEY UPDATE title=VALUES(title), body=VALUES(body);

UPDATE shop_settings SET setting_value='7', updated_at=NOW() WHERE setting_key='aftersale.window_days';
INSERT INTO shop_settings (setting_key, setting_value, updated_at)
SELECT 'aftersale.window_days', '7', NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM shop_settings WHERE setting_key='aftersale.window_days');

